/** Decode "nan" / "inf" / "-inf" strings of the fixtures. */
function dec(v: unknown): number {
  if (v === "nan") return Number.NaN;
  if (v === "inf") return Number.POSITIVE_INFINITY;
  if (v === "-inf") return Number.NEGATIVE_INFINITY;
  return Number(v);
}

function flat(value: unknown): number[] {
  if (Array.isArray(value)) return value.flatMap((v) => flat(v));
  return [typeof value === "bigint" ? Number(value) : Number(value)];
}

function shapeOf(data: unknown): number[] {
  const shape: number[] = [];
  let cur: unknown = data;
  while (Array.isArray(cur)) {
    shape.push(cur.length);
    cur = cur[0];
  }
  return shape;
}

/** Build a tensor; arrays holding bigint literals become exact int64 tensors. */
function t(data: unknown, dtype: DT = "float64"): Tensor {
  const values = Array.isArray(data) ? flatValues(data) : [data];
  if (values.some((v) => typeof v === "bigint")) {
    const out = tensor(new BigInt64Array(values.map((v) => BigInt(v as bigint))), {
      dtype: "int64",
    });
    return out.reshape(shapeOf(data));
  }
  return tensor(data as number[], { dtype });
}

function flatValues(value: unknown[]): unknown[] {
  return value.flatMap((v) => (Array.isArray(v) ? flatValues(v) : [v]));
}

function expectClose(got: unknown, want: readonly unknown[], tol: number, label = ""): void {
  const g = flat(got);
  expect(g.length, label).toBe(want.length);
  for (let i = 0; i < g.length; i++) {
    const e = dec(want[i]);
    const v = g[i] as number;
    if (Number.isNaN(e)) {
      expect(Number.isNaN(v), `${label}[${i}] should be NaN, got ${v}`).toBe(true);
    } else if (!Number.isFinite(e)) {
      expect(v, `${label}[${i}]`).toBe(e);
    } else {
      const err = Math.abs(v - e) / Math.max(1, Math.abs(e));
      expect(err, `${label}[${i}] got ${v} want ${e}`).toBeLessThanOrEqual(tol);
    }
  }
}

function bigs(x: Tensor): bigint[] {
  return x.toArray() as bigint[];
}

const ALL_DTYPES = [
  "bool",
  "uint8",
  "int32",
  "int64",
  "float16",
  "bfloat16",
  "float32",
  "float64",
] as const;

describe("promoteTypes", () => {
  it("matches torch.promote_types for every pair of real dtypes", () => {
    for (const a of ALL_DTYPES) {
      for (const b of ALL_DTYPES) {
        expect(promoteTypes(a, b), `${a} + ${b}`).toBe(FX.promote[a][b]);
        expect(promoteTypes(b, a), `${b} + ${a}`).toBe(FX.promote[a][b]);
      }
    }
  });

  it("follows the owner's rules", () => {
    expect(promoteTypes("int32", "float32")).toBe("float32");
    expect(promoteTypes("int64", "float16")).toBe("float16");
    expect(promoteTypes("uint8", "bfloat16")).toBe("bfloat16");
    expect(promoteTypes("float16", "bfloat16")).toBe("float32");
    expect(promoteTypes("bool", "uint8")).toBe("uint8");
    expect(promoteTypes("uint8", "int32")).toBe("int32");
    expect(promoteTypes("float32", "float64")).toBe("float64");
  });

  it("handles complex dtypes and rejects strings", () => {
    expect(promoteTypes("complex64", "float64")).toBe("complex128");
    expect(promoteTypes("complex64", "int32")).toBe("complex64");
    expect(promoteTypes("complex128", "float16")).toBe("complex128");
    expect(promoteTypes("complex64", "complex128")).toBe("complex128");
    expect(() => promoteTypes("string", "float32")).toThrow(DTypeError);
    expect(() => promoteTypes("int32", "string")).toThrow(DTypeError);
  });

  it("toFloatDType keeps floats and maps everything else to float32", () => {
    for (const d of ["float16", "bfloat16", "float32", "float64"] as const) {
      expect(toFloatDType(d)).toBe(d);
      expect(isFloatDType(d)).toBe(true);
    }
    for (const d of ["bool", "uint8", "int32", "int64"] as const) {
      expect(toFloatDType(d)).toBe("float32");
      expect(isFloatDType(d)).toBe(false);
    }
  });
});

describe("binary ops promote their operands like PyTorch", () => {
  const fns: Record<string, (a: Tensor, b: Tensor) => Tensor> = {
    add,
    sub,
    mul,
    div,
    pow,
    maximum,
    minimum,
    floorDiv,
    mod,
  };

  it("matches torch for dtype pairs and values (120 cases)", () => {
    expect(FX.binary.length).toBeGreaterThan(100);
    for (const [op, da, db, a, b, dtype, values] of FX.binary) {
      const r = (fns[op] as (a: Tensor, b: Tensor) => Tensor)(t(a, da), t(b, db));
      const label = `${op}(${da}, ${db})`;
      expect(r.dtype, label).toBe(dtype);
      expectClose(
        r.toArray(),
        values,
        dtype === "float16" || dtype === "bfloat16" ? 1e-2 : 1e-6,
        label
      );
    }
  });

  it("no longer throws for mixed dtypes", () => {
    expect(() => add(t([1], "float32"), t([1], "float64"))).not.toThrow();
    expect(add(t([1, 2], "int32"), t([0.5, 0.5], "float32")).toArray()).toEqual([1.5, 2.5]);
  });

  it("float16 with bfloat16 gives float32 (value from torch)", () => {
    const r = add(t([0.1], "float16"), t([0.1], "bfloat16"));
    expect(r.dtype).toBe("float32");
    expect(r.toArray()).toEqual([Math.fround(0.2000732421875)]);
  });

  it("broadcasts and promotes together", () => {
    const a = t(
      [
        [1, 2, 3],
        [4, 5, 6],
      ],
      "int32"
    );
    const b = t([0.5, 1.5, 2.5], "float32");
    const r = mul(a, b);
    expect(r.dtype).toBe("float32");
    expect(r.shape).toEqual([2, 3]);
    expect(r.toArray()).toEqual([
      [0.5, 3, 7.5],
      [2, 7.5, 15],
    ]);
  });

  it("promotes non-contiguous views", () => {
    const m = t(
      [
        [1, 2, 3],
        [4, 5, 6],
      ],
      "int32"
    );
    const r = add(transpose(m), t([[0.25], [0.5], [0.75]], "float64"));
    expect(r.dtype).toBe("float64");
    expect(r.toArray()).toEqual([
      [1.25, 4.25],
      [2.5, 5.5],
      [3.75, 6.75],
    ]);
  });

  it("promotes 0-d operands and empty tensors", () => {
    const r = sub(t(10, "int32"), t([0.5, 1.5], "float32"));
    expect(r.dtype).toBe("float32");
    expect(r.toArray()).toEqual([9.5, 8.5]);
    const empty = add(t([], "int32").reshape([0, 3]), t([1, 2, 3], "float32"));
    expect(empty.dtype).toBe("float32");
    expect(empty.shape).toEqual([0, 3]);
    expect(empty.size).toBe(0);
  });

  it("maximum and minimum propagate NaN across promoted dtypes", () => {
    const hi = maximum(t([Number.NaN, 1], "float32"), t([0, 2], "int32"));
    expect(hi.dtype).toBe("float32");
    const hv = hi.toArray() as number[];
    expect(Number.isNaN(hv[0])).toBe(true);
    expect(hv[1]).toBe(2);
    const lo = minimum(t([3, 1], "int64"), t([Number.NaN, 2], "float64"));
    expect(lo.dtype).toBe("float64");
    expect(Number.isNaN((lo.toArray() as number[])[0])).toBe(true);
  });

  it("int64 stays exact when promoted with smaller integers", () => {
    const big = 2n ** 62n + 1n;
    const r = add(t([big], "int64"), t([1], "int32"));
    expect(r.dtype).toBe("int64");
    expect(bigs(r)).toEqual([2n ** 62n + 2n]);
  });

  it("bool operands behave as the smallest integer type", () => {
    expect(sub(t([true, false], "bool"), t([1, 1], "int32")).toArray()).toEqual([0, -1]);
    expect(add(t([true, false], "bool"), t([true, true], "bool")).dtype).toBe("bool");
    expect(() => sub(t([true], "bool"), t([true], "bool"))).toThrow(DTypeError);
  });

  it("int division and negative integer exponents give float32", () => {
    const q = div(t([1, 2], "int32"), t([2, 4], "int32"));
    expect(q.dtype).toBe("float32");
    expect(q.toArray()).toEqual([0.5, 0.5]);
    const p = pow(t([2, 4], "int32"), t([-1, 2], "int32"));
    expect(p.dtype).toBe("float32");
    expect(p.toArray()).toEqual([0.5, 16]);
    expect(reciprocal(t([2, 4], "int64")).dtype).toBe("float32");
    expect(reciprocal(t([2, 4], "float16")).dtype).toBe("float16");
  });

  it("rejects string tensors with a DTypeError", () => {
    expect(() => add(t(["a"], "string"), t([1], "float32"))).toThrow(DTypeError);
    expect(() => maximum(t([1], "float32"), t(["a"], "string"))).toThrow(DTypeError);
  });

  it("number scalars never upcast a tensor", () => {
    const a = addScalar(t([1, 2], "int32"), 0.5);
    expect(a.dtype).toBe("float32");
    expect(a.toArray()).toEqual([1.5, 2.5]);
    expect(mulScalar(t([1, 2], "int64"), 0.5).dtype).toBe("float32");
    expect(mulScalar(t([true, false], "bool"), 0.5).dtype).toBe("float32");
    expect(addScalar(t([1, 2], "float32"), 0.5).dtype).toBe("float32");
    expect(addScalar(t([1, 2], "float16"), 0.5).dtype).toBe("float16");
    expect(addScalar(t([1, 2], "int32"), 3).dtype).toBe("int32");
    expect(clip(t([1, 2, 3], "int32"), 1.5, 2.5).dtype).toBe("float32");
    expect(clip(t([1, 2, 3], "int32"), 2, 3).dtype).toBe("int32");
    expect(clip(t([1, 2, 3], "float16"), 2, 3).dtype).toBe("float16");
  });

  it("neg and abs keep the integer dtype", () => {
    for (const d of ["int32", "int64", "uint8"] as const) {
      expect(abs(t([1, 2], d)).dtype).toBe(d);
    }
    expect(neg(t([1, 2], "int32")).dtype).toBe("int32");
    expect(neg(t([1, 2], "int64")).dtype).toBe("int64");
  });
});

describe("comparisons and logical ops accept mixed dtypes", () => {
  it("compare across dtypes and return bool", () => {
    const e = equal(t([1, 2], "int32"), t([1, 2.5], "float32"));
    expect(e.dtype).toBe("bool");
    expect(e.toArray()).toEqual([1, 0]);
    expect(greater(t([0.5, 3], "float16"), t([1, 2], "bfloat16")).toArray()).toEqual([0, 1]);
    expect(equal(t([2n ** 62n + 1n], "int64"), t([2 ** 62], "float64")).toArray()).toEqual([0]);
    expect(isclose(t([1, 2], "int32"), t([1, 2.000001], "float64")).toArray()).toEqual([1, 1]);
  });

  it("logical ops mix dtypes", () => {
    const r = logicalAnd(t([1, 0, 2], "float32"), t([1, 1, 0], "int64"));
    expect(r.dtype).toBe("bool");
    expect(r.toArray()).toEqual([1, 0, 0]);
  });
});

describe("float ops keep the input float dtype", () => {
  const x = FX.unary.x;
  const fns: Record<string, (v: Tensor) => Tensor> = {
    exp,
    log: (v) => log(abs(v)),
    sqrt: (v) => sqrt(abs(v)),
    expm1,
    log1p: (v) => log1p(abs(v)),
    log2: (v) => log2(abs(v)),
    log10: (v) => log10(abs(v)),
    rsqrt: (v) => rsqrt(abs(v)),
    square,
    cbrt,
    exp2,
    sin,
    cos,
    tan,
    atan,
    sinh,
    cosh,
    tanh,
    asinh,
    asin: (v) => asin(mulScalar(v, 0.25)),
    acos: (v) => acos(mulScalar(v, 0.25)),
    acosh: (v) => acosh(addScalar(abs(v), 1)),
    atanh: (v) => atanh(mulScalar(v, 0.25)),
    floor,
    ceil,
    trunc,
    round,
    sigmoid,
    relu,
    relu6: (v) => relu6(mulScalar(v, 3)),
    leakyRelu: (v) => leakyRelu(v, 0.2),
    elu: (v) => elu(v, 1.3),
    selu,
    celu: (v) => celu(v, 1.5),
    gelu_tanh: (v) => gelu(v),
    gelu_none: (v) => gelu(v, { approximate: "none" }),
    softplus,
    softsign,
    logSigmoid,
    hardsigmoid,
    hardswish,
    hardtanh,
    hardshrink: (v) => hardshrink(v, 1.2),
    softshrink: (v) => softshrink(v, 1.2),
    tanhshrink,
    swish,
    mish,
  };

  it("float64 results match numpy and torch to 1e-12", () => {
    for (const [name, want] of Object.entries(FX.unary.ops)) {
      const r = (fns[name] as (v: Tensor) => Tensor)(t(x, "float64"));
      expect(r.dtype, name).toBe("float64");
      expectClose(r.toArray(), want, 1e-12, name);
    }
  });

  it("float32 results keep float32 and are rounded float64 results", () => {
    for (const [name, want] of Object.entries(FX.unary.ops)) {
      const r = (fns[name] as (v: Tensor) => Tensor)(t(x, "float32"));
      expect(r.dtype, name).toBe("float32");
      expectClose(r.toArray(), want, 5e-6, name);
    }
  });

  it("float16 and bfloat16 keep their dtype and values sit on the dtype grid", () => {
    const e16 = exp(t([0, 1, 2], "float16"));
    expect(e16.dtype).toBe("float16");
    expect(e16.toArray()).toEqual([1, 2.71875, 7.390625]);
    const eb = exp(t([0, 1, 2], "bfloat16"));
    expect(eb.dtype).toBe("bfloat16");
    expect(eb.toArray()).toEqual([1, 2.71875, 7.375]);
    const s16 = sigmoid(t([-1, 0, 1], "float16"));
    expect(s16.dtype).toBe("float16");
    expect(s16.toArray()).toEqual([0.26904296875, 0.5, 0.73095703125]);
    const se = selu(t([-1, 0, 1], "float16"));
    expect(se.dtype).toBe("float16");
    expect(se.toArray()).toEqual([-1.111328125, 0, 1.05078125]);
    expect(atan2(t([1], "float16"), t([1], "float16")).dtype).toBe("float16");
    expect(softmax(t([[1, 2]], "bfloat16")).dtype).toBe("bfloat16");
  });

  it("integer and bool input computes in float32", () => {
    for (const d of ["bool", "uint8", "int32", "int64"] as const) {
      const v = t([1, 1, 0], d);
      for (const [name, f] of Object.entries({
        exp,
        log,
        sqrt,
        sin,
        tanh,
        sigmoid,
        gelu: (u: Tensor) => gelu(u),
        softmax: (u: Tensor) => softmax(u),
        logSoftmax: (u: Tensor) => logSoftmax(u),
        swish,
        mish,
        softplus,
        elu: (u: Tensor) => elu(u),
        leakyRelu: (u: Tensor) => leakyRelu(u),
        tanhshrink,
        hardswish,
        selu,
        rsqrt,
        expm1,
        log1p,
      } as Record<string, (u: Tensor) => Tensor>)) {
        expect(f(v).dtype, `${name}(${d})`).toBe("float32");
      }
    }
    const e = exp(t([0, 1, 2], "int32"));
    expectClose(e.toArray(), [1, Math.E, Math.exp(2)], 1e-6);
  });

  it("atan2 promotes both operands", () => {
    const r = atan2(t([1, -1], "int32"), t([-1, -1], "float32"));
    expect(r.dtype).toBe("float32");
    expectClose(r.toArray(), [2.356194490192345, -2.356194490192345], 1e-6);
    expect(atan2(t([1], "float32"), t([1], "float64")).dtype).toBe("float64");
    expect(atan2(t([1], "int64"), t([1], "int32")).dtype).toBe("float32");
  });

  it("strided views keep the dtype and read the logical layout", () => {
    const m = t(
      [
        [1, 2],
        [3, 4],
      ],
      "float32"
    );
    const r = sqrt(transpose(m));
    expect(r.dtype).toBe("float32");
    expect(r.toArray()).toEqual([
      [Math.fround(1), Math.fround(Math.sqrt(3))],
      [Math.fround(Math.sqrt(2)), Math.fround(2)],
    ]);
  });

  it("empty and 0-d tensors", () => {
    const empty = exp(t([], "float32"));
    expect(empty.dtype).toBe("float32");
    expect(empty.size).toBe(0);
    const zero = sqrt(t(4, "float16"));
    expect(zero.dtype).toBe("float16");
    expect(zero.shape).toEqual([]);
    expect(zero.toArray()).toBe(2);
    expect(exp(t(Number.NaN, "float32")).toArray()).toBeNaN();
  });

  it("softmax and logSoftmax keep float dtypes and match torch", () => {
    const x2 = FX.softmax.x;
    for (const dtype of ["float64", "float32"] as const) {
      const tol = dtype === "float64" ? 1e-12 : 5e-6;
      const a = softmax(t(x2, dtype), 0);
      expect(a.dtype).toBe(dtype);
      expectClose(a.toArray(), flat(FX.softmax.s0), tol);
      expectClose(softmax(t(x2, dtype), 1).toArray(), flat(FX.softmax.s1), tol);
      expectClose(softmax(t(x2, dtype), -1).toArray(), flat(FX.softmax.s1), tol);
      const l = logSoftmax(t(x2, dtype), 0);
      expect(l.dtype).toBe(dtype);
      expectClose(l.toArray(), flat(FX.softmax.l0), tol);
      expectClose(logSoftmax(t(x2, dtype), -1).toArray(), flat(FX.softmax.l1), tol);
    }
  });
});

describe("integer-preserving elementwise ops", () => {
  it("floor, ceil, trunc and round return integers unchanged", () => {
    for (const d of ["int32", "int64", "uint8"] as const) {
      for (const f of [floor, ceil, trunc, round]) {
        const r = f(t([1, 2, 3], d));
        expect(r.dtype).toBe(d);
        expect(flat(r.toArray())).toEqual([1, 2, 3]);
      }
    }
    expect(floor(t([true, false], "bool")).dtype).toBe("float32");
  });

  it("round with negative decimals rounds integers to tens (numpy.round)", () => {
    const r = round(t([15, 24, 25, 35, -15], "int32"), -1);
    expect(r.dtype).toBe("int32");
    expect(r.toArray()).toEqual([20, 20, 20, 40, -20]);
    expect(bigs(round(t([1234n], "int64"), -2))).toEqual([1200n]);
  });

  it("square keeps integer dtypes and wraps like numpy", () => {
    expect(square(t([3, -4], "int32")).toArray()).toEqual([9, 16]);
    expect(square(t([3, -4], "int32")).dtype).toBe("int32");
    expect(square(t([65536], "int32")).toArray()).toEqual([0]);
    expect(square(t([20], "uint8")).toArray()).toEqual([144]);
    expect(bigs(square(t([3037000500n], "int64")))).toEqual([BigInt.asIntN(64, 3037000500n ** 2n)]);
    expect(square(t([true, false], "bool")).dtype).toBe("int32");
  });

  it("relu and relu6 keep integer dtypes exactly", () => {
    expect(relu(t([-3, 4], "int32")).dtype).toBe("int32");
    expect(relu(t([-3, 4], "int32")).toArray()).toEqual([0, 4]);
    expect(relu6(t([-3, 4, 9], "int32")).toArray()).toEqual([0, 4, 6]);
    expect(bigs(relu6(t([-3n, 40n], "int64")))).toEqual([0n, 6n]);
    expect(relu(t([200], "uint8")).dtype).toBe("uint8");
    expect(relu(t([true, false], "bool")).dtype).toBe("int32");
    expect(bigs(relu(t([2n ** 62n + 1n], "int64")))).toEqual([2n ** 62n + 1n]);
  });
});

describe("reductions and scans", () => {
  const inputs = FX.inputs;
  const shape = FX.shape;
  const reducers: Record<string, (x: Tensor, axis?: number | number[], kd?: boolean) => Tensor> = {
    sum,
    mean,
    min,
    max,
    median,
    prod,
    nanmedian,
    nanprod,
  };
  const scans: Record<string, (x: Tensor, axis?: number) => Tensor> = {
    cumsum,
    cumprod,
    nancumsum,
  };
  const searches: Record<string, (x: Tensor, axis?: number, kd?: boolean) => Tensor> = {
    argmax,
    argmin,
    nanargmax,
    nanargmin,
  };

  function run(c: ReductionCase, dtype: DT): Tensor {
    const [fn, inp, axis, keepdims, extra] = c;
    const x = t((inputs[inp] ?? []).map(dec), dtype).reshape(shape);
    const ax = axis ?? undefined;
    const e = (extra ?? {}) as Extra;
    switch (fn) {
      case "variance":
        return variance(x, ax, keepdims, e.ddof);
      case "std":
        return std(x, ax, keepdims, e.ddof);
      case "nanvar":
        return nanvar(x, ax, keepdims, e.ddof);
      case "nanquantile":
        return nanquantile(x, e.q as number | number[], ax, keepdims);
      case "diff":
        return diff(x, e.n, ax as number);
      case "cumsum":
      case "cumprod":
      case "nancumsum":
        return (scans[fn] as (x: Tensor, axis?: number) => Tensor)(
          x,
          typeof ax === "number" ? ax : undefined
        );
      case "argmax":
      case "argmin":
      case "nanargmax":
      case "nanargmin":
        return (searches[fn] as (x: Tensor, axis?: number, kd?: boolean) => Tensor)(
          x,
          typeof ax === "number" ? ax : undefined,
          keepdims
        );
      default:
        return (reducers[fn] as (x: Tensor, axis?: number | number[], kd?: boolean) => Tensor)(
          x,
          ax,
          keepdims
        );
    }
  }

  for (const dtype of ["float64", "float32"] as const) {
    it(`matches numpy on ${FX.reductions.length} cases with ${dtype} input (dtype, shape, values)`, () => {
      const tol = dtype === "float64" ? 1e-10 : 3e-5;
      for (const c of FX.reductions) {
        const [fn, inp, axis, keepdims, , expected, expShape, expDtype] = c;
        const label = `${fn}(${inp}, axis=${JSON.stringify(axis)}, keepdims=${keepdims}) [${dtype}]`;
        const r = run(c, dtype);
        expect(r.dtype, label).toBe(expDtype === "same" ? dtype : expDtype);
        expect(r.shape, label).toEqual(expShape);
        if (expDtype === "int32") {
          expect(flat(r.toArray()), label).toEqual(expected.map(dec));
        } else {
          expectClose(r.toArray(), expected, tol, label);
        }
      }
    });
  }

  it("integer-preserving ops keep int32 and int64; uint8 and bool give int32", () => {
    expect(sum(t([1, 2, 3], "int32")).dtype).toBe("int32");
    expect(sum(t([1, 2, 3], "int64")).dtype).toBe("int64");
    expect(sum(t([1, 0, 1], "bool")).dtype).toBe("int32");
    expect(sum(t([250, 10], "uint8")).toArray()).toBe(260);
    expect(sum(t([250, 10], "uint8")).dtype).toBe("int32");
    expect(prod(t([2, 3], "int32")).dtype).toBe("int32");
    expect(prod(t([2, 3], "int64")).dtype).toBe("int64");
    expect(min(t([2, 3], "int32")).dtype).toBe("int32");
    expect(max(t([2, 3], "int64")).dtype).toBe("int64");
    expect(max(t([2, 3], "uint8")).dtype).toBe("uint8");
    expect(cumsum(t([1, 2, 3], "int32")).dtype).toBe("int32");
    expect(cumsum(t([1, 2, 3], "int32")).toArray()).toEqual([1, 3, 6]);
    expect(cumsum(t([1, 2, 3], "int64")).dtype).toBe("int64");
    expect(cumsum(t([1, 0, 1], "bool")).dtype).toBe("int32");
    expect(cumsum(t([100, 200], "uint8")).toArray()).toEqual([100, 300]);
    expect(cumprod(t([1, 2, 3, 4], "int32")).toArray()).toEqual([1, 2, 6, 24]);
    expect(cumprod(t([1, 2, 3, 4], "int32")).dtype).toBe("int32");
    expect(cumprod(t([1, 2, 3], "int64")).dtype).toBe("int64");
    const d32 = diff(t([1, 4, 9, 16], "int32"));
    expect(d32.dtype).toBe("int32");
    expect(d32.toArray()).toEqual([3, 5, 7]);
    expect(diff(t([1, 4, 9, 16], "int64")).dtype).toBe("int64");
    expect(diff(t([5, 3], "uint8")).toArray()).toEqual([-2]);
    expect(diff(t([1, 4, 9, 16], "int32"), 2).toArray()).toEqual([2, 2]);
  });

  it("integer scans throw instead of wrapping on overflow", () => {
    expect(() => cumsum(t([2_000_000_000, 2_000_000_000], "int32"))).toThrow(DataValidationError);
    expect(() => cumprod(t([100000, 100000], "int32"))).toThrow(DataValidationError);
    expect(() => diff(t([-2_000_000_000, 2_000_000_000], "int32"))).toThrow(DataValidationError);
    expect(() => sum(t([2_000_000_000, 2_000_000_000], "int32"))).toThrow(DataValidationError);
  });

  it("float sums keep their dtype and accumulate in float64", () => {
    for (const d of ["float16", "bfloat16", "float32", "float64"] as const) {
      expect(sum(t([0.5, 0.25], d)).dtype).toBe(d);
      expect(cumsum(t([0.5, 0.25], d)).dtype).toBe(d);
      expect(prod(t([0.5, 0.25], d)).dtype).toBe(d);
      expect(diff(t([0.5, 0.25], d)).dtype).toBe(d);
    }
    // float32 spacing at 2^24 is 2: a float32 running sum would stay at 16777216.
    expect(sum(t([16777216, 1, 1], "float32")).toArray()).toBe(16777218);
    expect(sum(t([0.1, 0.2, 0.3], "float32")).toArray()).toBe(Math.fround(0.1 + 0.2 + 0.3));
  });

  it("mean, variance, std and median of integer input give float32", () => {
    for (const d of ["bool", "uint8", "int32", "int64"] as const) {
      const v = t([1, 0, 1, 1], d);
      expect(mean(v).dtype, `mean ${d}`).toBe("float32");
      expect(variance(v).dtype, `variance ${d}`).toBe("float32");
      expect(std(v).dtype, `std ${d}`).toBe("float32");
      expect(median(v).dtype, `median ${d}`).toBe("float32");
    }
    expect(mean(t([1, 2, 4], "int32")).toArray()).toBe(Math.fround(7 / 3));
    expect(median(t([1, 2, 3, 4], "int32")).toArray()).toBe(2.5);
    expect(variance(t([1, 2, 3, 4, 5], "int32")).toArray()).toBe(2);
    expect(variance(t([1, 2, 3, 4, 5], "int32"), undefined, false, 1).toArray()).toBe(2.5);
    for (const d of ["float16", "bfloat16", "float32", "float64"] as const) {
      expect(mean(t([1, 2], d)).dtype).toBe(d);
      expect(std(t([1, 2], d)).dtype).toBe(d);
      expect(median(t([1, 2], d)).dtype).toBe(d);
    }
  });

  it("std takes the square root before rounding", () => {
    const v = t([1, 2, 3, 4], "float32");
    expect(std(v).toArray()).toBe(Math.fround(Math.sqrt(1.25)));
    expect(std(t([1, 2], "float16")).toArray()).toBe(0.5);
  });

  it("empty reductions", () => {
    expect(sum(t([], "float32")).toArray()).toBe(0);
    expect(sum(t([], "float32")).dtype).toBe("float32");
    expect(Number.isNaN(mean(t([], "float32")).toArray() as number)).toBe(true);
    expect(mean(t([], "float32")).dtype).toBe("float32");
    expect(prod(t([], "float64")).toArray()).toBe(1);
    expect(() => max(t([], "float32"))).toThrow(InvalidParameterError);
    expect(() => median(t([], "float32"))).toThrow(InvalidParameterError);
  });

  it("0-d tensors", () => {
    expect(sum(t(3, "float32")).toArray()).toBe(3);
    expect(sum(t(3, "int32")).dtype).toBe("int32");
    expect(mean(t(3, "int32")).dtype).toBe("float32");
    expect(cumsum(t(3, "int32")).shape).toEqual([1]);
  });

  it("strided views", () => {
    const m = t(
      [
        [1, 2, 3],
        [4, 5, 6],
      ],
      "int32"
    );
    const v = transpose(m);
    expect(sum(v, 0).toArray()).toEqual([6, 15]);
    expect(sum(v, 0).dtype).toBe("int32");
    expect(mean(v, 1).toArray()).toEqual([2.5, 3.5, 4.5]);
    expect(cumsum(v, 0).toArray()).toEqual([
      [1, 4],
      [3, 9],
      [6, 15],
    ]);
    expect(diff(v, 1, 0).toArray()).toEqual([
      [1, 1],
      [1, 1],
    ]);
  });
});

describe("argmax and argmin", () => {
  it("return int32 indices and use the first occurrence on ties", () => {
    const x = t([1, 3, 3, 2], "float32");
    expect(argmax(x).dtype).toBe("int32");
    expect(argmax(x).toArray()).toBe(1);
    expect(argmin(t([2, 1, 1, 3], "float64")).toArray()).toBe(1);
    expect(argmax(t([-0, 0], "float64")).toArray()).toBe(0);
  });

  it("NaN propagates as the index of the first NaN", () => {
    expect(argmax(t([1, Number.NaN, Number.NaN, 3])).toArray()).toBe(1);
    expect(argmin(t([1, Number.NaN, 0])).toArray()).toBe(1);
    expect(
      argmax(
        t([
          [1, 2],
          [Number.NaN, 0],
        ]),
        0
      ).toArray()
    ).toEqual([1, 0]);
    expect(argmax(t([Number.NaN, Number.NaN])).toArray()).toBe(0);
  });

  it("flattens without an axis and honours keepdims and negative axes", () => {
    const m = t(
      [
        [1, 9, 3],
        [7, 2, 8],
      ],
      "int32"
    );
    expect(argmax(m).toArray()).toBe(1);
    expect(argmax(m, undefined, true).shape).toEqual([1, 1]);
    expect(argmax(m, undefined, true).toArray()).toEqual([[1]]);
    expect(argmax(m, 1).toArray()).toEqual([1, 2]);
    expect(argmax(m, -1).toArray()).toEqual([1, 2]);
    expect(argmax(m, 1, true).shape).toEqual([2, 1]);
    expect(argmax(m, 0).toArray()).toEqual([1, 0, 1]);
    expect(argmin(m, 0).toArray()).toEqual([0, 1, 0]);
    expect(argmin(m, "columns").toArray()).toEqual([0, 1]);
    expect(argmin(m, 1, true).toArray()).toEqual([[0], [1]]);
  });

  it("reads non-contiguous views through their strides", () => {
    const m = t(
      [
        [1, 9, 3],
        [7, 2, 8],
      ],
      "float32"
    );
    const v = transpose(m);
    expect(argmax(v).toArray()).toBe(
      argmax(
        t(
          [
            [1, 7],
            [9, 2],
            [3, 8],
          ],
          "float32"
        )
      ).toArray()
    );
    expect(argmax(v, 0).toArray()).toEqual([1, 2]);
    expect(argmin(v, 1).toArray()).toEqual([0, 1, 0]);
  });

  it("compares int64 values exactly", () => {
    const a = t([2n ** 62n + 1n, 2n ** 62n], "int64");
    expect(argmax(a).toArray()).toBe(0);
    expect(argmin(a).toArray()).toBe(1);
    const b = t([2n ** 62n, 2n ** 62n + 1n], "int64");
    expect(argmax(b).toArray()).toBe(1);
    expect(
      argmin(
        t(
          [
            [5n, 1n],
            [2n, 7n],
          ],
          "int64"
        ),
        1
      ).toArray()
    ).toEqual([1, 0]);
  });

  it("works for every numeric dtype, 0-d and size-1 inputs", () => {
    for (const d of ALL_DTYPES) {
      const r = argmax(t([0, 1, 0], d));
      expect(r.toArray(), d).toBe(1);
      expect(r.dtype).toBe("int32");
    }
    expect(argmax(t(5, "float32")).toArray()).toBe(0);
    expect(argmin(t(5, "float32")).shape).toEqual([]);
    expect(argmax(t([4], "float32"), 0).toArray()).toBe(0);
    expect(argmax(t([4], "float32"), 0).shape).toEqual([]);
  });

  it("rejects empty slices, bad axes and strings", () => {
    expect(() => argmax(t([]))).toThrow(InvalidParameterError);
    expect(() => argmin(t([]).reshape([0, 3]), 1).shape).not.toThrow();
    expect(argmin(t([]).reshape([0, 3]), 1).shape).toEqual([0]);
    expect(() => argmax(t([]).reshape([3, 0]), 1)).toThrow(InvalidParameterError);
    expect(() => argmax(t([1, 2]), 1)).toThrow(InvalidParameterError);
    expect(() => argmax(t(5), 0)).toThrow(InvalidParameterError);
    expect(() => argmax(t(["a"], "string"))).toThrow(DTypeError);
  });
});

describe("NaN-ignoring reductions", () => {
  it("nanargmax and nanargmin skip NaN and keep int32", () => {
    expect(nanargmax(t([Number.NaN, 3, 7, Number.NaN])).toArray()).toBe(2);
    expect(nanargmin(t([Number.NaN, 3, 1, 1, Number.NaN])).toArray()).toBe(2);
    expect(nanargmax(t([Number.NaN, 3, 7], "float32")).dtype).toBe("int32");
    expect(
      nanargmax(
        t([
          [Number.NaN, 2],
          [5, Number.NaN],
        ]),
        0
      ).toArray()
    ).toEqual([1, 0]);
    expect(
      nanargmin(
        t([
          [Number.NaN, 2],
          [5, Number.NaN],
        ]),
        1,
        true
      ).toArray()
    ).toEqual([[1], [0]]);
    expect(nanargmax(t([1, 5, 2], "int32")).toArray()).toBe(1);
    expect(nanargmax(t([2n ** 62n, 2n ** 62n + 1n], "int64")).toArray()).toBe(1);
  });

  it("nanargmax and nanargmin raise on an all-NaN slice like numpy", () => {
    expect(() => nanargmax(t([Number.NaN, Number.NaN]))).toThrow(DataValidationError);
    expect(() =>
      nanargmin(
        t([
          [1, Number.NaN],
          [2, Number.NaN],
        ]),
        0
      )
    ).toThrow(DataValidationError);
    expect(() => nanargmin(t([]))).toThrow(InvalidParameterError);
  });

  it("nanvar ignores NaN, honours ddof and gives NaN for too few values", () => {
    expect(nanvar(t([1, Number.NaN, 3])).toArray()).toBe(1);
    expect(nanvar(t([1, Number.NaN, 3]), undefined, false, 1).toArray()).toBe(2);
    expect(nanvar(t([Number.NaN, 3])).toArray()).toBe(0);
    expect(nanvar(t([Number.NaN, 3]), undefined, false, 1).toArray()).toBeNaN();
    expect(nanvar(t([Number.NaN, Number.NaN])).toArray()).toBeNaN();
    expect(nanvar(t([])).toArray()).toBeNaN();
    expect(
      nanvar(
        t([
          [1, Number.NaN],
          [3, 5],
        ]),
        1
      ).toArray()
    ).toEqual([0, 1]);
    expect(
      nanvar(
        t([
          [1, Number.NaN],
          [3, 5],
        ]),
        1,
        true
      ).shape
    ).toEqual([2, 1]);
    expect(() => nanvar(t([1]), undefined, false, -1)).toThrow(InvalidParameterError);
  });

  it("nanmedian ignores NaN and gives NaN for all-NaN or empty slices", () => {
    expect(nanmedian(t([1, Number.NaN, 3, 10])).toArray()).toBe(3);
    expect(
      nanmedian(
        t([
          [1, Number.NaN],
          [3, 5],
        ]),
        1
      ).toArray()
    ).toEqual([1, 4]);
    expect(nanmedian(t([Number.NaN, Number.NaN])).toArray()).toBeNaN();
    expect(nanmedian(t([])).toArray()).toBeNaN();
    expect(nanmedian(t([1, 2, 4], "int32")).dtype).toBe("float32");
    expect(nanmedian(t([1, 2, 4], "float16")).dtype).toBe("float16");
  });

  it("nanprod treats NaN as one", () => {
    expect(nanprod(t([2, Number.NaN, 4])).toArray()).toBe(8);
    expect(nanprod(t([Number.NaN, Number.NaN])).toArray()).toBe(1);
    expect(nanprod(t([])).toArray()).toBe(1);
    expect(
      nanprod(
        t([
          [2, Number.NaN],
          [3, 5],
        ]),
        0
      ).toArray()
    ).toEqual([6, 5]);
    expect(
      nanprod(
        t([
          [2, Number.NaN],
          [3, 5],
        ]),
        1,
        true
      ).shape
    ).toEqual([2, 1]);
    expect(nanprod(t([2, 3], "int32")).dtype).toBe("int32");
    expect(nanprod(t([true, true], "bool")).dtype).toBe("int32");
    expect(nanprod(t([2, Number.NaN], "float32")).dtype).toBe("float32");
  });

  it("nancumsum treats NaN as zero", () => {
    expect(nancumsum(t([1, Number.NaN, 3])).toArray()).toEqual([1, 1, 4]);
    expect(
      nancumsum(
        t([
          [1, Number.NaN],
          [3, 5],
        ])
      ).toArray()
    ).toEqual([1, 1, 4, 9]);
    expect(
      nancumsum(
        t([
          [1, Number.NaN],
          [3, 5],
        ]),
        0
      ).toArray()
    ).toEqual([
      [1, 0],
      [4, 5],
    ]);
    expect(nancumsum(t([1, 2], "int32")).dtype).toBe("int32");
    expect(nancumsum(t([1, Number.NaN], "float32")).dtype).toBe("float32");
    expect(
      nancumsum(
        transpose(
          t([
            [1, Number.NaN],
            [3, 5],
          ])
        ),
        1
      ).toArray()
    ).toEqual([
      [1, 4],
      [0, 5],
    ]);
  });

  it("nanquantile: shapes, dtype, validation and special slices", () => {
    const x = t([1, Number.NaN, 3, 5], "float32");
    expect(nanquantile(x, 0.5).toArray()).toBe(3);
    expect(nanquantile(x, 0.5).dtype).toBe("float32");
    expect(nanquantile(x, 0.5).shape).toEqual([]);
    expect(nanquantile(x, [0.25, 1]).toArray()).toEqual([2, 5]);
    expect(nanquantile(x, [0.25, 1]).shape).toEqual([2]);
    const m = t([
      [1, 2, Number.NaN],
      [4, Number.NaN, Number.NaN],
    ]);
    expect(nanquantile(m, [0, 0.5], 1).shape).toEqual([2, 2]);
    expect(nanquantile(m, [0, 0.5], 1).toArray()).toEqual([
      [1, 4],
      [1.5, 4],
    ]);
    expect(nanquantile(m, 0.5, 1, true).shape).toEqual([2, 1]);
    expect(nanquantile(t([Number.NaN, Number.NaN]), 0.5).toArray()).toBeNaN();
    expect(nanquantile(t([]), 0.5).toArray()).toBeNaN();
    expect(nanquantile(t([Number.NaN, 5]), [0, 0.5, 1]).toArray()).toEqual([5, 5, 5]);
    expect(nanquantile(t([1, 2, 3, 4], "int32"), 0.5).dtype).toBe("float32");
    expect(nanquantile(t([1, 2, 3, 4], "float16"), 0.5).dtype).toBe("float16");
    expect(nanquantile(t([1, 2, 3, 4]), 0.5).toArray()).toBe(2.5);
    expect(() => nanquantile(x, 1.5)).toThrow(InvalidParameterError);
    expect(() => nanquantile(x, [0.5, -0.1])).toThrow(InvalidParameterError);
    expect(() => nanquantile(x, Number.NaN)).toThrow(InvalidParameterError);
    expect(() => nanquantile(x, 0.5, 3)).toThrow(InvalidParameterError);
  });

  it("nanquantile interpolates infinite values to the infinity", () => {
    expect(nanquantile(t([1, Number.POSITIVE_INFINITY]), [0, 0.25, 1]).toArray()).toEqual([
      1,
      Number.POSITIVE_INFINITY,
      Number.POSITIVE_INFINITY,
    ]);
    expect(nanquantile(t([-Infinity, 1, Infinity]), 0.25).toArray()).toBe(Number.NEGATIVE_INFINITY);
    expect(nanquantile(t([Infinity, Infinity]), 0.5).toArray()).toBe(Number.POSITIVE_INFINITY);
  });

  it("nanquantile reads strided views", () => {
    const m = transpose(
      t([
        [1, Number.NaN, 3],
        [2, 4, Number.NaN],
      ])
    );
    expect(nanquantile(m, 0.5, 0).toArray()).toEqual([2, 3]);
  });
});

describe("digitize returns int32", () => {
  const { x, bins, left, right, dbins, dleft } = FX.numerical.digitize;
  it("matches numpy.digitize (left, right and decreasing bins)", () => {
    const xt = t((x as unknown[]).map(dec), "float32");
    const bt = t(bins, "float32");
    const l = digitize(xt, bt);
    expect(l.dtype).toBe("int32");
    expect(l.toArray()).toEqual(left);
    expect(digitize(xt, bt, true).toArray()).toEqual(right);
    expect(digitize(xt, bt, true).dtype).toBe("int32");
    const dl = digitize(xt, t(dbins, "float32"));
    expect(dl.dtype).toBe("int32");
    expect(dl.toArray()).toEqual(dleft);
  });

  it("keeps the shape and handles empty bins and empty input", () => {
    const r = digitize(
      t([
        [1, 2],
        [3, 4],
      ]),
      t([2.5])
    );
    expect(r.shape).toEqual([2, 2]);
    expect(r.toArray()).toEqual([
      [0, 0],
      [1, 1],
    ]);
    expect(digitize(t([1, 2]), t([])).toArray()).toEqual([0, 0]);
    const e = digitize(t([]), t([1, 2]));
    expect(e.dtype).toBe("int32");
    expect(e.size).toBe(0);
  });
});

describe("interp, gradient and stacking follow the dtype rules", () => {
  const { x, xp, fp, y } = FX.numerical.interp;
  const { f, y: gy, y2 } = FX.numerical.gradient;

  it("interp matches numpy and returns the promoted float dtype", () => {
    const xv = (x as unknown[]).map(dec);
    const r64 = interp(t(xv), t(xp), t(fp));
    expect(r64.dtype).toBe("float64");
    expectClose(r64.toArray(), y, 1e-12);
    const r32 = interp(t(xv, "float32"), t(xp, "float32"), t(fp, "float32"));
    expect(r32.dtype).toBe("float32");
    expectClose(r32.toArray(), y, 1e-6);
    expect(interp(t([0.5], "int32"), t(xp, "int32"), t(fp, "int32")).dtype).toBe("float32");
    expect(interp(t([0.5], "float32"), t(xp, "float32"), t(fp, "float64")).dtype).toBe("float64");
  });

  it("gradient matches numpy and keeps the float dtype", () => {
    expectClose(gradient(t(f)).toArray(), gy, 1e-12);
    expectClose(gradient(t(f), 0.5).toArray(), y2, 1e-12);
    expect(gradient(t(f, "float32")).dtype).toBe("float32");
    expect(gradient(t(f, "int32")).dtype).toBe("float32");
    expect(gradient(t(f, "float64")).dtype).toBe("float64");
    expect(gradient(t(f, "float32"), t([0, 1, 2, 3, 4], "float64")).dtype).toBe("float64");
  });

  it("hstack and vstack promote like binary ops", () => {
    expect(hstack([t([1], "int32"), t([2.5], "float32")]).dtype).toBe("float32");
    expect(hstack([t([1], "int64"), t([2.5], "float16")]).dtype).toBe("float16");
    expect(vstack([t([1], "float16"), t([2], "bfloat16")]).dtype).toBe("float32");
    expect(hstack([t([1], "uint8"), t([2], "int32")]).dtype).toBe("int32");
  });
});

describe("gelu options and the extra activations", () => {
  const x = FX.unary.x;

  it("gelu defaults to the tanh form and accepts { approximate }", () => {
    const tanhForm = gelu(t(x));
    expectClose(tanhForm.toArray(), FX.unary.ops.gelu_tanh, 1e-12);
    expectClose(gelu(t(x), {}).toArray(), FX.unary.ops.gelu_tanh, 1e-12);
    expectClose(gelu(t(x), { approximate: "tanh" }).toArray(), FX.unary.ops.gelu_tanh, 1e-12);
    expectClose(gelu(t(x), { approximate: "none" }).toArray(), FX.unary.ops.gelu_none, 1e-12);
  });

  it("gelu still accepts the old positional string", () => {
    expectClose(gelu(t(x), "none").toArray(), FX.unary.ops.gelu_none, 1e-12);
    expectClose(gelu(t(x), "tanh").toArray(), FX.unary.ops.gelu_tanh, 1e-12);
  });

  it("gelu validates approximate", () => {
    expect(() => gelu(t(x), { approximate: "erf" as "none" })).toThrow(InvalidParameterError);
    expect(() => gelu(t(x), "bad" as "none")).toThrow(InvalidParameterError);
    expect(() => gelu(t(["a"], "string"), { approximate: "none" })).toThrow(DTypeError);
  });

  it("gelu(-Infinity) is the limit 0", () => {
    expect(gelu(t([-Infinity]), { approximate: "none" }).toArray()).toEqual([0]);
    expect(gelu(t([-Infinity])).toArray()).toEqual([0]);
  });

  it("edge values (NaN and infinities) match torch", () => {
    const xe = FX.edge.x.map(dec);
    const fns: Record<string, (v: Tensor) => Tensor> = {
      relu,
      relu6,
      selu,
      celu2: (v) => celu(v, 2),
      softsign,
      hardsigmoid,
      hardswish,
      logSigmoid,
      hardshrink: (v) => hardshrink(v),
      softshrink: (v) => softshrink(v),
      elu: (v) => elu(v),
      softplus,
      tanhshrink,
      sigmoid,
      leakyRelu: (v) => leakyRelu(v),
      hardtanh: (v) => hardtanh(v),
    };
    for (const [name, want] of Object.entries(FX.edge.ops)) {
      const r = (fns[name] as (v: Tensor) => Tensor)(t(xe));
      expect(r.dtype, name).toBe("float64");
      expectClose(r.toArray(), want, 1e-12, name);
    }
  });

  it("parameters: celu alpha, shrink lambd", () => {
    expectClose(celu(t([-1, 0, 1]), 2).toArray(), [-0.7869386805747332, 0, 1], 1e-12);
    expectClose(hardshrink(t([-2, -0.3, 0.3, 2])).toArray(), [-2, 0, 0, 2], 1e-12);
    expectClose(softshrink(t([-2, -0.3, 0.3, 2])).toArray(), [-1.5, 0, 0, 1.5], 1e-12);
    expect(hardshrink(t([0.5, -0.5, 0.51]), 0.5).toArray()).toEqual([0, 0, 0.51]);
    expect(softshrink(t([1, -1, 3]), 1).toArray()).toEqual([0, 0, 2]);
    expect(hardshrink(t([1, 2]), 0).toArray()).toEqual([1, 2]);
    expect(() => celu(t([1]), 0)).toThrow(InvalidParameterError);
    expect(() => celu(t([1]), Number.NaN)).toThrow(InvalidParameterError);
    expect(() => hardshrink(t([1]), -1)).toThrow(InvalidParameterError);
    expect(() => softshrink(t([1]), -0.5)).toThrow(InvalidParameterError);
    expect(() => softshrink(t([1]), Number.NaN)).toThrow(InvalidParameterError);
  });

  it("new activations keep float dtypes, give float32 for integers, and reject strings", () => {
    const fns = {
      selu,
      celu: (v: Tensor) => celu(v),
      softsign,
      hardsigmoid,
      hardswish,
      logSigmoid,
      hardshrink: (v: Tensor) => hardshrink(v),
      softshrink: (v: Tensor) => softshrink(v),
    } as Record<string, (v: Tensor) => Tensor>;
    for (const [name, f] of Object.entries(fns)) {
      for (const d of ["float16", "bfloat16", "float32", "float64"] as const) {
        expect(f(t([-1, 0.5], d)).dtype, `${name} ${d}`).toBe(d);
      }
      for (const d of ["bool", "uint8", "int32", "int64"] as const) {
        expect(f(t([1, 0], d)).dtype, `${name} ${d}`).toBe("float32");
      }
      expect(() => f(t(["a"], "string")), name).toThrow(DTypeError);
    }
  });

  it("new activations on empty, 0-d and strided input", () => {
    expect(selu(t([], "float32")).size).toBe(0);
    expect(hardswish(t(1, "float32")).shape).toEqual([]);
    expect(logSigmoid(t(0, "float64")).toArray()).toBeCloseTo(-Math.LN2, 14);
    const m = t(
      [
        [1, -1],
        [2, -2],
      ],
      "float32"
    );
    const v = softsign(transpose(m));
    expect(v.shape).toEqual([2, 2]);
    expectClose(v.toArray(), [0.5, 2 / 3, -0.5, -2 / 3], 1e-6);
  });

  it("relu6 values", () => {
    expect(relu6(t([-2, 3, 8, Number.NaN])).toArray()).toEqual([0, 3, 6, Number.NaN]);
  });

  it("hardtanh keeps integer dtypes for integer bounds", () => {
    expect(hardtanh(t([-3, 0, 3], "int32")).dtype).toBe("int32");
    expect(hardtanh(t([-3, 0, 3], "int32")).toArray()).toEqual([-1, 0, 1]);
    expect(hardtanh(t([-3, 0, 3], "float32"), -0.5, 0.5).dtype).toBe("float32");
  });
});
